"""Offline tests for the query-scoped PQL.Assert 0.8.0 helper used by the live contract tests."""

from __future__ import annotations

import pytest


from tests.pql_assert_library import (  # noqa: E402 - after the importorskip guard
    field,
    load_library,
    missing_definitions,
    model_function_names,
    with_definitions,
)
from pql_test.odcs.udf import parse_functions  # noqa: E402

SUITE = """\
// generated by pql-test
DEFINE
\tFUNCTION M.DataQuality.DEV.Tests = () =>
\t\tUNION(
\t\t\tPQL.Assert.Col.NullCountShouldBeAtMost("n", 'T', 'T'[a], 0),
\t\t\tPQL.Assert.Tbl.ShouldExist("e", "T")
\t\t)

EVALUATE M.DataQuality.DEV.Tests()
"""


def test_library_fixture_loads_0_8_0():
    given = "the vendored PQL.Assert 0.8.0 package"
    should = "load LibraryVersion() and the 0.8-only functions"

    library = load_library()

    assert {"PQL.Assert.LibraryVersion", "PQL.Assert.Col.NullCountShouldBeAtMost"} <= set(library), (
        f"{given}: {should}"
    )


def test_only_functions_the_model_lacks_are_defined():
    given = "a suite calling one 0.8-only function and one function the model has"
    should = "define only the 0.8-only function"

    needed = missing_definitions(SUITE, {"PQL.Assert.Tbl.ShouldExist"}, load_library())

    assert [fn.name for fn in needed] == ["PQL.Assert.Col.NullCountShouldBeAtMost"], f"{given}: {should}"


def test_library_dependencies_are_defined_first():
    given = "a library function that calls another library function the model lacks"
    should = "define the dependency before the caller"
    library = {
        fn.name: fn
        for fn in parse_functions(
            "function 'PQL.Assert.A' =\n\t\t() => PQL.Assert.B()\nfunction 'PQL.Assert.B' =\n\t\t() => 1\n"
        )
    }

    needed = missing_definitions("EVALUATE { PQL.Assert.A() }", set(), library)

    assert [fn.name for fn in needed] == ["PQL.Assert.B", "PQL.Assert.A"], f"{given}: {should}"


def test_definitions_go_at_the_top_of_the_define_block():
    given = "a generated suite and one missing function"
    should = "insert the FUNCTION right after DEFINE, leaving the suite unchanged"
    needed = missing_definitions(SUITE, {"PQL.Assert.Tbl.ShouldExist"}, load_library())

    text = with_definitions(SUITE, needed)

    before, after = text.split("\tFUNCTION M.DataQuality.DEV.Tests", 1)
    assert (
        before.startswith("// generated by pql-test\nDEFINE\n\tFUNCTION PQL.Assert.Col.NullCountShouldBeAtMost = ("),
        "\tFUNCTION M.DataQuality.DEV.Tests" + after == SUITE.split("DEFINE\n", 1)[1],
    ) == (True, True), f"{given}: {should}\n{text}"


def test_a_query_without_define_gets_one():
    given = "a bare EVALUATE query"
    should = "get a DEFINE block before EVALUATE"
    (fn,) = parse_functions("function 'PQL.Assert.B' =\n\t\t() => 1\n")

    text = with_definitions("EVALUATE { PQL.Assert.B() }", [fn])

    assert text == "DEFINE\n\tFUNCTION PQL.Assert.B = () => 1\n\nEVALUATE { PQL.Assert.B() }", f"{given}: {should}"


def test_model_function_names_falls_back_to_the_dmv():
    given = "a model where INFO.FUNCTIONS() fails"
    should = "list the names from TMSCHEMA_FUNCTIONS"

    def execute(_conn, query):
        if "INFO.FUNCTIONS" in query:
            raise RuntimeError("unknown function")
        return [{"Name": "PQL.Assert.Tbl.ShouldExist"}]

    assert model_function_names(object(), execute) == {"PQL.Assert.Tbl.ShouldExist"}, f"{given}: {should}"


@pytest.mark.parametrize("key", ["[Passed]", "Passed", "T[Passed]"])
def test_field_matches_bare_and_bracketed_names(key):
    assert field({key: True}, "Passed") is True, f"given column {key!r}: should match Passed"
